import type { RunResult, SDKMessage } from "@cursor/sdk";
import type { AgentRunPayload } from "../agent/types.js";

export function displayToolName(event: Extract<SDKMessage, { type: "tool_call" }>): string {
  if (event.name !== "mcp" || !isRecord(event.args)) return event.name;
  const provider = typeof event.args.providerIdentifier === "string" ? event.args.providerIdentifier : "mcp";
  const toolName = typeof event.args.toolName === "string" ? event.args.toolName : "unknown";
  return `${provider}.${toolName}`;
}

export function summarizeDraft(draft: AgentRunPayload["draft"]): Record<string, unknown> {
  return {
    sections: draft.sections.map((section) => ({
      sectionId: section.sectionId,
      title: section.title,
      candidateIds: section.candidateIds,
      text: section.text,
      textLength: section.text.length,
    })),
    fullTextWithSectionMarkers: draft.fullTextWithSectionMarkers,
    finalTtsText: draft.finalTtsText,
  };
}

export function summarizeToolResult(value: unknown): unknown {
  if (Array.isArray(value)) {
    return {
      count: value.length,
      items: value.slice(0, 50),
    };
  }
  if (typeof value === "string") {
    return truncate(value, 8000);
  }
  return value;
}

export type StreamSummary = {
  counts: Record<string, number>;
  assistantText: string[];
  thinkingText: string[];
  statuses: Array<{ status: string; message?: string }>;
  tasks: Array<{ status?: string; text?: string }>;
  requests: Array<{ requestId: string }>;
};

export function createStreamSummary(): StreamSummary {
  return {
    counts: {},
    assistantText: [],
    thinkingText: [],
    statuses: [],
    tasks: [],
    requests: [],
  };
}

export function appendStreamEvent(summary: StreamSummary, event: SDKMessage): void {
  summary.counts[event.type] = (summary.counts[event.type] ?? 0) + 1;
  if (event.type === "assistant") {
    const text = event.message.content
      .map((block) => {
        if (block.type === "text") return block.text;
        return `[tool_use:${block.name}]`;
      })
      .join("");
    if (text.trim()) summary.assistantText.push(text);
    return;
  }
  if (event.type === "thinking") {
    if (event.text.trim()) summary.thinkingText.push(event.text);
    return;
  }
  if (event.type === "status") {
    summary.statuses.push({ status: event.status, message: event.message });
    return;
  }
  if (event.type === "task") {
    summary.tasks.push({ status: event.status, text: event.text });
    return;
  }
  if (event.type === "request") {
    summary.requests.push({ requestId: event.request_id });
  }
}

export function redactSecrets(data: unknown): unknown {
  if (typeof data === "string") {
    return data
      .replace(/cursor_[A-Za-z0-9_-]+/g, "cursor_***")
      .replace(/sk-lf-[A-Za-z0-9_-]+/g, "sk-lf-***")
      .replace(/pk-lf-[A-Za-z0-9_-]+/g, "pk-lf-***")
      .replace(/tr_[A-Za-z0-9_-]+/g, "tr_***");
  }
  return data;
}

export function truncate(value: string, maxLength: number): string {
  if (value.length <= maxLength) return value;
  return `${value.slice(0, maxLength)}... [truncated ${value.length - maxLength} chars]`;
}

export function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function numberField(value: unknown): number {
  return typeof value === "number" ? value : 0;
}

export function summarizeRunResult(result: RunResult): Record<string, unknown> {
  return {
    runId: result.id,
    status: result.status,
    resultPreview: truncate(result.result ?? "", 4000),
    durationMs: result.durationMs,
    git: result.git,
  };
}

export type TracingProviderName = "langfuse" | "traceroot";

export interface TracingBackend {
  readonly provider: TracingProviderName;
  start(): void;
  flush(): Promise<void>;
  shutdown(): Promise<void>;
}

import { LangfuseSpanProcessor } from "@langfuse/otel";
import { NodeSDK } from "@opentelemetry/sdk-node";
import { redactSecrets } from "../tracing-utils.js";
import type { TracingBackend } from "./types.js";

export function createLangfuseBackend(env: NodeJS.ProcessEnv = process.env): TracingBackend | null {
  const publicKey = env.LANGFUSE_PUBLIC_KEY?.trim();
  const secretKey = env.LANGFUSE_SECRET_KEY?.trim();
  const baseUrl = env.LANGFUSE_BASE_URL?.trim();

  if (!publicKey || !secretKey) {
    return null;
  }

  const spanProcessor = new LangfuseSpanProcessor({
    publicKey,
    secretKey,
    baseUrl: baseUrl || undefined,
    exportMode: "immediate",
    mask: ({ data }) => redactSecrets(data),
  });
  const sdk = new NodeSDK({
    spanProcessors: [spanProcessor],
  });

  return {
    provider: "langfuse",
    start() {
      sdk.start();
    },
    async flush() {
      try {
        await spanProcessor.forceFlush();
      } catch {}
    },
    async shutdown() {
      try {
        await sdk.shutdown();
      } catch {}
    },
  };
}

import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-proto";
import { NodeSDK } from "@opentelemetry/sdk-node";
import { BatchSpanProcessor } from "@opentelemetry/sdk-trace-base";
import type { TracingBackend } from "./types.js";

const DEFAULT_HOST = "https://app.traceroot.ai";

export function createTraceRootBackend(env: NodeJS.ProcessEnv = process.env): TracingBackend | null {
  const apiKey = env.TRACEROOT_API_KEY?.trim();
  if (!apiKey) {
    return null;
  }

  const host = (env.TRACEROOT_HOST_URL?.trim() || DEFAULT_HOST).replace(/\/$/, "");
  const exporter = new OTLPTraceExporter({
    url: `${host}/api/v1/public/traces`,
    headers: {
      Authorization: `Bearer ${apiKey}`,
    },
  });
  const spanProcessor = new BatchSpanProcessor(exporter);
  const sdk = new NodeSDK({
    spanProcessors: [spanProcessor],
  });

  return {
    provider: "traceroot",
    start() {
      sdk.start();
    },
    async flush() {
      try {
        await spanProcessor.forceFlush();
      } catch {}
    },
    async shutdown() {
      try {
        await sdk.shutdown();
      } catch {}
    },
  };
}

import { startObservation } from "@langfuse/tracing";
import { SpanStatusCode, trace, type Span } from "@opentelemetry/api";
import type { TracingProviderName } from "./providers/types.js";

export type ObservationType =
  | "agent"
  | "tool"
  | "generation"
  | "retriever"
  | "evaluator"
  | "span"
  | "event";

export type ObservationAttributes = {
  input?: unknown;
  output?: unknown;
  metadata?: Record<string, unknown>;
  level?: "DEFAULT" | "WARNING" | "ERROR";
  statusMessage?: string;
};

export interface ObservationHandle {
  update(attributes: ObservationAttributes & Record<string, unknown>): void;
  end(): void;
  startChild(name: string, attributes: ObservationAttributes, asType: ObservationType): ObservationHandle;
}

type LangfuseObservation = {
  update(attributes: Record<string, unknown>): LangfuseObservation;
  end(): void;
  startObservation(
    name: string,
    attributes?: Record<string, unknown>,
    options?: { asType: string },
  ): LangfuseObservation;
};

const OTEL_TRACER = trace.getTracer("daily-briefing-agent", "1.0.0");

export function startObservationHandle(
  provider: TracingProviderName,
  name: string,
  attributes: ObservationAttributes,
  asType: ObservationType,
  parent?: ObservationHandle,
): ObservationHandle {
  if (provider === "langfuse") {
    return createLangfuseHandle(name, attributes, asType, parent);
  }
  return createOtelHandle(name, attributes, asType, parent);
}

function createLangfuseHandle(
  name: string,
  attributes: ObservationAttributes,
  asType: ObservationType,
  parent?: ObservationHandle,
): ObservationHandle {
  const langfuseParent = parent as LangfuseObservationHandle | undefined;
  const observation = langfuseParent
    ? langfuseParent.raw.startObservation(name, attributes, { asType })
    : (startObservation(name, attributes, { asType }) as LangfuseObservation);
  return new LangfuseObservationHandle(observation);
}

class LangfuseObservationHandle implements ObservationHandle {
  constructor(readonly raw: LangfuseObservation) {}

  update(attributes: ObservationAttributes & Record<string, unknown>): void {
    this.raw.update(attributes);
  }

  end(): void {
    this.raw.end();
  }

  startChild(name: string, attributes: ObservationAttributes, asType: ObservationType): ObservationHandle {
    return createLangfuseHandle(name, attributes, asType, this);
  }
}

function createOtelHandle(
  name: string,
  attributes: ObservationAttributes,
  asType: ObservationType,
  parent?: ObservationHandle,
): ObservationHandle {
  const otelParent = parent as OtelObservationHandle | undefined;
  const span = OTEL_TRACER.startSpan(
    name,
    {
      attributes: buildTraceRootAttributes(asType, attributes),
    },
    otelParent ? trace.setSpanContext(trace.setSpan(trace.active(), otelParent.span), otelParent.span.spanContext()) : undefined,
  );
  applyObservationLevel(span, attributes);
  return new OtelObservationHandle(span);
}

class OtelObservationHandle implements ObservationHandle {
  constructor(readonly span: Span) {}

  update(attributes: ObservationAttributes & Record<string, unknown>): void {
    this.span.setAttributes(buildTraceRootAttributes(undefined, attributes));
    applyObservationLevel(this.span, attributes);
  }

  end(): void {
    this.span.end();
  }

  startChild(name: string, attributes: ObservationAttributes, asType: ObservationType): ObservationHandle {
    return createOtelHandle(name, attributes, asType, this);
  }
}

function buildTraceRootAttributes(
  asType: ObservationType | undefined,
  attributes: ObservationAttributes & Record<string, unknown>,
): Record<string, string> {
  const result: Record<string, string> = {};
  if (asType) {
    result["traceroot.span.type"] = mapTraceRootSpanType(asType);
  }
  if (attributes.input !== undefined) {
    result["traceroot.span.input"] = serializeAttribute(attributes.input);
  }
  if (attributes.output !== undefined) {
    result["traceroot.span.output"] = serializeAttribute(attributes.output);
  }
  if (attributes.metadata) {
    for (const [key, value] of Object.entries(attributes.metadata)) {
      result[`traceroot.span.metadata.${key}`] = serializeAttribute(value);
    }
  }
  if (attributes.statusMessage) {
    result["traceroot.span.metadata.statusMessage"] = attributes.statusMessage;
  }
  return result;
}

function mapTraceRootSpanType(asType: ObservationType): string {
  switch (asType) {
    case "agent":
      return "AGENT";
    case "tool":
      return "TOOL";
    case "generation":
      return "LLM";
    default:
      return "SPAN";
  }
}

function applyObservationLevel(span: Span, attributes: ObservationAttributes): void {
  if (attributes.level === "ERROR") {
    span.setStatus({
      code: SpanStatusCode.ERROR,
      message: attributes.statusMessage,
    });
    return;
  }
  if (attributes.level === "WARNING" && attributes.statusMessage) {
    span.setAttribute("traceroot.span.metadata.level", "WARNING");
  }
}

function serializeAttribute(value: unknown): string {
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

