import "dotenv/config";
import { createDailyBriefingTracerFromEnv } from "../src/observability/create-tracer-from-env.js";

async function main(): Promise<void> {
  const tracer = createDailyBriefingTracerFromEnv();
  const trace = tracer.startTrace({
    briefingDate: "2026-06-29",
    inputDir: "inputs",
    model: "composer-2.5",
    maxRevisions: 2,
  });
  trace.recordSourceProcessing({
    sources: {} as never,
    totals: { candidateCount: 3, discardedCount: 1, mustIncludeCount: 2 },
  });
  const run = trace.startAgentRun({
    kind: "initial",
    attempt: 0,
    prompt: "traceroot smoke test",
    agentId: "smoke-test",
    model: "composer-2.5",
  });
  run.end();
  trace.recordFinalResult({
    outline: { sections: [] } as never,
    draft: { sections: [], fullTextWithSectionMarkers: "smoke", finalTtsText: "smoke" } as never,
    revisionCount: 0,
  });
  trace.end();
  await tracer.flush?.();
  await tracer.shutdown?.();
  console.log("smoke trace exported");
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
});

